// Build the landing link. The two parameters are ROUTING HINTS ONLY.
// Nothing here mints, carries or accepts a token — access still comes from the demo session
// established in the browser plus the caller's own bearer.
const body = $('Orbit activated').first().json.body ?? $('Orbit activated').first().json;

const appBase = ($env.FRIDGEGRAPH_APP_URL || 'http://127.0.0.1:5189').replace(/\/$/, '');
const alertId = String(body.alertId || '');
const personaId = String(body.personaId || 'kendra');

if (!alertId) {
  throw new Error('orbit-activation-sms: alertId is required');
}
if (!/^oa_[A-Za-z0-9]+$/.test(alertId)) {
  throw new Error('orbit-activation-sms: alertId does not look like an Orbit alert id');
}
if (!/^[a-z0-9_-]+$/i.test(personaId)) {
  throw new Error('orbit-activation-sms: personaId must be a public persona id');
}

const link = `${appBase}/orbit?persona=${encodeURIComponent(personaId)}&alert=${encodeURIComponent(alertId)}`;

return [{
  json: {
    alertId,
    personaId,
    link,
    message: `FridgeGraph Orbit: ${body.childName ? body.childName + ' - ' : ''}an alert is live. Open it: ${link}`,
    // The recipient is supplied by the operator (GHL contact id), never a phone number in the repo.
    contactId: $env.FRIDGEGRAPH_OPERATOR_CONTACT_ID || '',
  },
}];
